import * as React from "react";
import { Pagination } from "../pagination";
import "./Timeline.scss";
import TimelineInfo, { TimelineInfoProps } from "./TimelineInfo/TimelineInfo";
import { useMemo, useState } from "react";
import clsx from "clsx";

export interface TimelineProps {
  /**
   * Array of timeline info to display
   */
  content: TimelineInfoProps[];
  /**
   * Toggle to show pagination
   * @default true
   */
  showPagination?: boolean;
  /**
   * Toggle to show vertical line on the left
   * @default true
   */
  showLine?: boolean;
  /**
   * Toggle to show x number of info per page
   * @default 2
   */
  pageRange?: number;
}

const Timeline = ({
  content,
  showPagination = true,
  showLine = true,
  pageRange = 2,
}: TimelineProps) => {
  const [page, setPage] = useState(1);

  const currentRenderContent = useMemo(() => {
    return content.filter((_, i) => Math.floor(i / pageRange) === page - 1);
  }, [page, content, pageRange]);

  const handlePageChange = (pageNumber: number) => {
    setPage(pageNumber);
  };

  const totalPages = Math.ceil(content.length / pageRange);

  return (
    <div className="timeline-container">
      {currentRenderContent.map((c, i) => {
        const isLast = i === currentRenderContent.length - 1;
        const key = c.id ?? `${c.title}-${c.subtitle}-${i}`;
        return (
          <div key={key}>
            <TimelineInfo
              icon={c.icon}
              iconStatus={c.iconStatus}
              title={c.title}
              subtitle={c.subtitle}
              content={c.content}
              showLine={showLine && !isLast}
            />
            {!isLast && (
              <div
                className={clsx("timeline-gap", { "hide-line": !showLine })}
              />
            )}
          </div>
        );
      })}
      {showPagination && (
        <div className="timeline-pagination-container">
          <Pagination
            id="timeline-pagination"
            type="responsive"
            totalPages={totalPages}
            onPageChange={handlePageChange}
            onItemsPerPageChange={() => {}}
          />
        </div>
      )}
    </div>
  );
};

export default Timeline;
